    color: var(--laser-tumbler-simple-cyan-4);
    font-size: 16px;
}

.pricing-notes ul {
    margin: 0;
    padding-left: 20px;
}

.pricing-notes li {
    margin: 8px 0;
    color: var(--print-ink-soft);
    font-size: 14px;
}

/* ===== Additional Charges Warning ===== */
.pricing-additional-charges {
    margin-top: 25px;
    padding: 20px;
    background: var(--amber-100);
    border-left: 4px solid var(--bs-warning);
    border-radius: 4px;
}

.pricing-additional-charges h4 {
    margin: 0 0 10px;
    color: var(--bs-warning-ink);
    font-size: 16px;
}

.pricing-additional-charges ul {
    margin: 0;
    padding-left: 20px;
}

.pricing-additional-charges li {
    margin: 8px 0;
    color: var(--bs-warning-ink);
    font-size: 14px;
    font-weight: 500;
}

/* ===== Product Gallery ===== */
.gallery-section {
    background: white;
    border-radius: 8px;
    padding: 40px;
    margin-bottom: 30px;
    box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
}

.gallery-section h2 {
    font-size: 28px;
    margin: 0 0 20px;
    color: var(--print-green);
}

.product-gallery {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 20px;
}

.gallery-item {
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid var(--gray-200);
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
}

.gallery-item:hover {
    transform: translateY(-4px);
    box-shadow: 0 4px 12px rgb(0 0 0 / 15%);
}

.gallery-thumbnail {
    width: 100%;
    height: auto;
    display: block;
}

/* ===== Lightbox ===== */
.lightbox {
